// Chapter-level fallback: research this session confirmed Chapter 72 (iron/steel
// primary & semi-finished) is 100% MFN Free across all 394 tracked codes, and
// Chapters 73/76 are Free except the specific finished-goods exceptions listed
// above in MFN_RATES. Codes not in MFN_RATES for these chapters fall back to Free.
const MFN_FREE_CHAPTERS = ["72", "05"]; // Chapter 5 (animal products nes) verified 100% Free, zero exceptions in the full PDF pass
const MFN_FREE_DEFAULT_CHAPTERS = ["73", "76", "01", "02", "03"]; // free unless explicit exception above

function getMfnRate(code){
  if(!code) return null;
  const clean = code.trim();
  if(MFN_RATES[clean]) return { ...MFN_RATES[clean], source: "verified" };
  // Some data sources (surtax orders especially) specify a code at less than
  // full 10-digit precision, e.g. an 8-digit tariff item like "9406.90.20"
  // that's implicitly shorthand for "9406.90.20.00" and everything under it.
  // Try a normalized prefix match against the MFN_RATES keys before falling
  // back to the chapter-wide pattern — only auto-resolve if exactly one
  // verified key matches, to avoid guessing across genuinely different codes.
  const nc = normCode(clean);
  const candidateKeys = Object.keys(MFN_RATES).filter(k => normCode(k).startsWith(nc));
  if(candidateKeys.length === 1) return { ...MFN_RATES[candidateKeys[0]], source: "verified" };
  const chapter = clean.slice(0,2);
  if(MFN_FREE_CHAPTERS.includes(chapter)) return { type:"free", rate:null, note:"", source:"chapter-pattern" };
  if(MFN_FREE_DEFAULT_CHAPTERS.includes(chapter)) return { type:"free", rate:null, note:"", source:"chapter-pattern" };
  return null; // not yet researched
}

function formatMfnRate(mfn){
  if(!mfn) return "";
  if(mfn.type === "free") return "MFN: Free" + (mfn.source === "chapter-pattern" ? " (chapter pattern)" : "");
  if(mfn.type === "percent") return `MFN: ${mfn.rate}%`;
  if(mfn.type === "specific" || mfn.type === "compound") return `MFN: ${mfn.note}`;
  return "";
}

function matchedCodesWithMfn(codes){
  return codes.map(code => {
    const mfn = getMfnRate(code);
    const label = formatMfnRate(mfn);
    return label ? code + ' <span class="mono" style="opacity:0.75;">(' + label + ')</span>' : code;
  }).join(', ');
}


function findSafeguardMatches(query){
  const q = normCode(query);
  const qLower = (query || "").toLowerCase().trim();
  if(!q && !qLower) return [];
  return SAFEGUARD_MEASURES.filter(m => {
    const codeMatch = m.hsCodes.some(code => {
      const nc = normCode(code);
      return q && (nc.startsWith(q) || q.startsWith(nc));
    });
    const keywordMatch = qLower.length > 2 && m.productKeywords.some(kw => kw.includes(qLower) || qLower.includes(kw));
    return codeMatch || keywordMatch;
  });
}


function findSurtaxMatches(query){
  const q = normCode(query);
  if(!q) return [];
  return SURTAX_ORDERS.filter(o =>
    o.hsCodes.some(code => {
      const nc = normCode(code);
      return nc.startsWith(q) || q.startsWith(nc);
    })
  );
}



