// Checks whether an import date falls within a remission order's eligible
// window. null start/end means open-ended on that side. Returns true/false
// — but a true here means "worth investigating," not "confirmed eligible":
// the real eligibility conditions (end-use, schedule membership, business
// number) still need human review against eligibilityCondition/statusNote.
function importDateInWindow(order, importDateStr){
  if(!importDateStr) return true; // no date given — can't rule it out, surface it
  const d = new Date(importDateStr);
  if(isNaN(d)) return true;
  if(order.importWindow.start && d < new Date(order.importWindow.start)) return false;
  if(order.importWindow.end && d > new Date(order.importWindow.end)) return false;
  return true;
}

// Finds remission orders that relieve the given surtax order AND whose
// import-date window covers the given date. This is a filter to a
// candidate list for human review, not an automated eligibility
// determination — real eligibility depends on end-use, schedule
// membership, and other conditions that need a person to check.
function findRemissionMatches(surtaxRegNo, importDateStr){
  if(!surtaxRegNo) return [];
  return REMISSION_ORDERS.filter(r =>
    r.reliefFromRegNo.includes(surtaxRegNo) && importDateInWindow(r, importDateStr)
  );
}

// Precise rule-based check: does this surtax order apply to goods from
// the given country? Uses the structured originScope field, not fuzzy
// text matching against the free-text origin description.
function surtaxAppliesToCountry(order, country){
  if(!country) return true; // "Any origin" selected in dropdown — show all
  switch(order.originScope){
    case "US":         return country === "United States";
    case "China":      return country === "China";
    case "any":         return true;
    // Note: "exclude-US" is a slight misnomer kept for backward compatibility
    // with the case label — SOR/2025-148's own text excludes Canada, US, AND
    // Mexico (all three CUSMA partners), not just the US. Previously this
    // only checked for the US, so Mexico/Canada-origin goods incorrectly
    // showed this surtax as applicable.
    case "exclude-US": return country !== "United States" && country !== "Canada" && country !== "Mexico";
    // For orders that key off where the RAW MATERIAL was melted/poured or
    // smelted/cast — a fact that is independent of the finished good's
    // country of origin. These must show regardless of which finished-goods
    // origin is selected (except origins the order itself excludes), because
    // selecting e.g. "Germany" tells you nothing about where the underlying
    // steel/aluminum was actually melted or cast. Excludes US (per the
    // order's own text) and China (since the separate China Surtax Order
    // already covers China-origin goods and the two orders explicitly don't
    // stack).
    case "any-except-us-china": return country !== "United States" && country !== "China";
    default:            return false;
  }
}

function normCode(s){ return (s || "").toLowerCase().replace(/[.\s]/g, ""); }

// Find every SIMA_CASES entry that has an HS code matching the query
// (matches if the query is a prefix of the code, or the code is a prefix
// of the query — so searching "7610.12" or the full 10-digit code both work)
function findSimaMatches(query){
  const q = normCode(query);
  if(!q) return [];
  return SIMA_CASES.filter(c =>
    c.hsCodes.some(code => {
      const nc = normCode(code);
      return nc.startsWith(q) || q.startsWith(nc);
    })
  );
}

// Most scopeNote entries follow the pattern "[plain product description].
// KEY EXCLUSION(S)/ADDITIONAL EXCLUSION(S): [dense legal exception detail]".
// Split on that marker so the card can show the quick plain-language read
// up front and tuck the CBSA-precise exclusion language behind a toggle,
// rather than rewriting ~40 hand-written scope notes from scratch.
function splitScopeNote(note){
  if(!note) return { summary: '', details: null };
  const match = note.match(/\b(KEY EXCLUSIONS?|ADDITIONAL EXCLUSIONS?)\b/);
  if(!match) return { summary: note, details: null };
  return { summary: note.slice(0, match.index).trim(), details: note.slice(match.index).trim() };
}

